import React, { useEffect, useState, useRef } from "react";
import { io } from "socket.io-client";
import { useParams } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { fetchMessages, addIncomingMessage } from "../Features/ChatSlice";
import "../Styles/Chat.css";

const socket = io("http://localhost:3001");

const ChatPageStudent = () => {
  const { applicationId } = useParams();

  const dispatch = useDispatch();
  const { user } = useSelector((s) => s.users);
  const { messages } = useSelector((s) => s.chat);

  const [text, setText] = useState("");
  const endRef = useRef(null);

  // join room
  useEffect(() => {
    socket.emit("join_room", applicationId);
  }, [applicationId]);

  // load chat history from DB
  useEffect(() => {
    dispatch(fetchMessages(applicationId));
  }, [applicationId]);

  // incoming realtime messages
  useEffect(() => {
    socket.on("receive_message", (msg) => {
      dispatch(addIncomingMessage(msg));
    });

    return () => socket.off("receive_message");
  }, [dispatch]);

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // send message
  const sendMsg = () => {
    if (!text.trim()) return;

    socket.emit("send_message", {
      applicationId,
      senderEmail: user.email,
      senderRole: "student",
      message: text,
    });

    setText("");
  };

  return (
    <div className="chat-page">
      <h2 className="chat-title">
        Chat <span className="accent">Support</span>
      </h2>

      <div className="chat-box">
        {messages.map((msg, i) => (
          <div
            key={i}
            className={`chat-message ${
              msg.senderEmail === user.email ? "me" : "them"
            }`}
          >
            <p className="msg-text">{msg.message}</p>
            <span className="msg-time">
              {new Date(msg.createdAt).toLocaleTimeString()}
            </span>
          </div>
        ))}
        <div ref={endRef}></div>
      </div>

      <div className="chat-input-area">
        <input
          className="chat-input"
          placeholder="Write a message..."
          value={text}
          onChange={(e) => setText(e.target.value)}
        />

        <button className="send-btn" onClick={sendMsg}>
          Send ➤
        </button>
      </div>
    </div>
  );
};

export default ChatPageStudent;
